#include "test.h"

#define HAL_H
static U32 fake_time_us;

static void hal_delay_us(U32 delay_us) {
    fake_time_us += delay_us;
}

static U32 hal_now_us(void) {
    // Bound pin-wait commands generated by the malformed-packet test.
    fake_time_us += 1000000u;
    return fake_time_us;
}

static bool hal_time_expired_us(U32 start, U32 duration) {
    return (U32)(hal_now_us() - start) >= duration;
}

#define SWD_H
enum {
    SwdAck_Ok = 1u,
    SwdAck_Wait = 2u,
    SwdAck_Fault = 4u,
    SwdAck_Error = 8u,

    RamBase = 0x20000000u,
    RamSize = 4096u,
    DpIdcode = 0x0BC11477u,
};

typedef struct {
    U32 unused;
} Bsp_SwdPort;

typedef struct Target Target;

typedef struct {
    Target *target;
    U32 clock_hz;
    U8 turnaround;
    U8 idle_cycles;
    U8 pins;
    bool data_phase;
    bool connected;
    bool nreset_released;
} Swd;

struct Target {
    U32 dp_ctrl_stat;
    U32 dp_select;
    U32 dp_rdbuff;
    U32 ap_csw;
    U32 ap_tar;
    U16 wait_responses;
    U8 next_ack;
    U8 ram[RamSize];
};

static Target *active_target;

static U8 target_read_byte(Target const *target, U32 address) {
    if (address < RamBase || address - RamBase >= RamSize) return 0u;
    return target->ram[address - RamBase];
}

static void target_write_byte(Target *target, U32 address, U8 value) {
    if (address < RamBase || address - RamBase >= RamSize) return;
    target->ram[address - RamBase] = value;
}

static U32 target_transfer_size(Target const *target) {
    U32 size_code = target->ap_csw & 7u;
    return size_code == 0u ? 1u : size_code == 1u ? 2u : 4u;
}

static U32 target_mem_read(Target const *target) {
    U32 size = target_transfer_size(target);
    U32 value = 0u;
    for (U32 i = 0u; i < size; i++) {
        U32 shift = ((target->ap_tar + i) & 3u) * 8u;
        value |= (U32)target_read_byte(target, target->ap_tar + i) <<
                 shift;
    }
    return value;
}

static void target_mem_write(Target *target, U32 value) {
    U32 size = target_transfer_size(target);
    for (U32 i = 0u; i < size; i++) {
        U32 shift = ((target->ap_tar + i) & 3u) * 8u;
        target_write_byte(target, target->ap_tar + i,
                          (U8)(value >> shift));
    }
}

static void target_increment(Target *target) {
    U32 mode = (target->ap_csw >> 4) & 3u;
    if (mode == 0u || mode == 3u) return;
    U32 size = mode == 2u ? 4u : target_transfer_size(target);
    target->ap_tar = (target->ap_tar & ~0x3FFu) |
                     ((target->ap_tar + size) & 0x3FFu);
}

static U32 target_ap_read(Target *target, U32 address) {
    switch (address) {
    case 0x00u: return target->ap_csw;
    case 0x04u: return target->ap_tar;
    case 0x0Cu: {
        U32 value = target_mem_read(target);
        target_increment(target);
        return value;
    }
    case 0xFCu: return 0x24770011u;
    default: return 0u;
    }
}

static void target_ap_write(Target *target, U32 address, U32 value) {
    switch (address) {
    case 0x00u: target->ap_csw = value; break;
    case 0x04u: target->ap_tar = value; break;
    case 0x0Cu:
        target_mem_write(target, value);
        target_increment(target);
        break;
    default: break;
    }
}

static bool swd_init(Swd *swd, Bsp_SwdPort const *port) {
    if (!swd || !port || !active_target) return false;
    *swd = (Swd){
        .target = active_target,
        .clock_hz = 1000000u,
        .turnaround = 1u,
        .pins = (1u << 0) | (1u << 1) | (1u << 7),
        .nreset_released = true,
    };
    return true;
}

static void swd_connect(Swd *swd) {
    swd->connected = true;
}

static void swd_disconnect(Swd *swd) {
    swd->connected = false;
}

static U8 swd_transfer(Swd *swd, U8 request, U32 *data) {
    if (!swd || !swd->connected) return 0u;
    Target *target = swd->target;
    if (target->wait_responses != 0u) {
        target->wait_responses--;
        return SwdAck_Wait;
    }
    if (target->next_ack != 0u) {
        U8 ack = target->next_ack;
        target->next_ack = 0u;
        return ack;
    }

    bool ap = (request & 1u) != 0u;
    bool read = (request & 2u) != 0u;
    U32 address = request & 0x0Cu;
    if (ap) {
        U32 ap_address = (target->dp_select & 0xF0u) | address;
        if (read) {
            U32 previous = target->dp_rdbuff;
            target->dp_rdbuff = target_ap_read(target, ap_address);
            if (data) *data = previous;
        } else {
            target_ap_write(target, ap_address, data ? *data : 0u);
        }
        return SwdAck_Ok;
    }

    if (read) {
        U32 value = 0u;
        if (address == 0x00u) value = DpIdcode;
        else if (address == 0x04u) value = target->dp_ctrl_stat;
        else if (address == 0x0Cu) value = target->dp_rdbuff;
        if (data) *data = value;
    } else if (address == 0x04u) {
        target->dp_ctrl_stat = data ? *data : 0u;
        if ((target->dp_ctrl_stat & (1u << 28)) != 0u) {
            target->dp_ctrl_stat |= 1u << 29;
        }
        if ((target->dp_ctrl_stat & (1u << 30)) != 0u) {
            target->dp_ctrl_stat |= 1u << 31;
        }
    } else if (address == 0x08u) {
        target->dp_select = data ? *data : 0u;
    }
    return SwdAck_Ok;
}

static void swd_nreset_write(Swd *swd, bool released) {
    swd->nreset_released = released;
    if (released) swd->pins |= 1u << 7;
    else swd->pins &= (U8)~(1u << 7);
}

static U8 swd_pins_read(Swd const *swd) {
    return swd->pins;
}

static void swd_pins_write(Swd *swd, U8 value, U8 select) {
    swd->pins = (U8)((swd->pins & ~select) | (value & select));
    swd->nreset_released = (swd->pins & (1u << 7)) != 0u;
}

static bool swd_set_clock(Swd *swd, U32 requested_hz) {
    if (requested_hz < 10000u) return false;
    swd->clock_hz = Min(requested_hz, 1000000u);
    return true;
}

static void swd_sequence_out(Swd *swd, U32 count, U8 const *data) {
    (void)swd;
    (void)count;
    (void)data;
}

static void swd_sequence_in(Swd *swd, U32 count, U8 *data) {
    (void)swd;
    memset(data, 0, (count + 7u) / 8u);
}

static void swd__swdio_output(Swd *swd) {
    (void)swd;
}

static void swd__swdio_latch(Swd *swd, bool high) {
    if (high) swd->pins |= 1u << 1;
    else swd->pins &= (U8)~(1u << 1);
}

static void swd_idle(Swd *swd) {
    swd__swdio_output(swd);
    swd__swdio_latch(swd, true);
}

#include "../cmsis_dap.h"

static U16 execute(CmsisDap *dap, U8 const *request, U16 request_size,
                   U8 response[CmsisDapPacketSize]) {
    memset(response, 0xCC, CmsisDapPacketSize);
    return cmsis_dap_execute(dap, request, request_size,
                             response, CmsisDapPacketSize);
}

static void connect_probe(CmsisDap *dap) {
    U8 response[CmsisDapPacketSize];
    U8 request[] = {CmsisDapCommand_Connect, CmsisDapPort_Autodetect};
    CHECK(execute(dap, request, sizeof(request), response) == 2u);
    CHECK(response[0] == CmsisDapCommand_Connect);
    CHECK(response[1] == CmsisDapPort_Swd);
}

static void configure_mem_ap(CmsisDap *dap, U32 csw, U32 address) {
    U8 response[CmsisDapPacketSize];
    U8 request[] = {
        CmsisDapCommand_Transfer, 0u, 3u,
        0x08u, 0u, 0u, 0u, 0u,
        0x01u, 0u, 0u, 0u, 0u,
        0x05u, 0u, 0u, 0u, 0u,
    };
    write_le32(request + 9, csw);
    write_le32(request + 14, address);
    CHECK(execute(dap, request, sizeof(request), response) == 3u);
    CHECK(response[1] == 3u && response[2] == SwdAck_Ok);
}

static void test_basic_commands(CmsisDap *dap) {
    U8 response[CmsisDapPacketSize];

    U8 info[] = {CmsisDapCommand_Info, CmsisDapInfo_Capabilities};
    CHECK(execute(dap, info, sizeof(info), response) == 4u);
    CHECK(response[1] == 2u && response[2] == 1u && response[3] == 0u);

    U8 version[] = {CmsisDapCommand_Info, CmsisDapInfo_ProductFirmwareVersion};
    CHECK(execute(dap, version, sizeof(version), response) == 2u + sizeof("1.2.3-test"));
    CHECK(response[1] == sizeof("1.2.3-test"));
    CHECK(strcmp((char const *)response + 2, "1.2.3-test") == 0);

    connect_probe(dap);

    U8 clock[] = {CmsisDapCommand_SwjClock, 0x40u, 0x42u, 0x0Fu, 0u};
    CHECK(execute(dap, clock, sizeof(clock), response) == 2u);
    CHECK(response[1] == CmsisDapStatus_Ok);

    U8 configure[] = {CmsisDapCommand_SwdConfigure, 6u};
    CHECK(execute(dap, configure, sizeof(configure), response) == 2u);
    CHECK(response[1] == CmsisDapStatus_Ok);

    U32 before_reset = fake_time_us;
    U8 reset[] = {CmsisDapCommand_ResetTarget};
    CHECK(execute(dap, reset, sizeof(reset), response) == 3u);
    CHECK(response[1] == CmsisDapStatus_Ok && response[2] == 1u);
    CHECK(dap->swd.nreset_released);
    CHECK(fake_time_us - before_reset == 10000u);
}

static void test_memory_transfers(CmsisDap *dap) {
    U8 response[CmsisDapPacketSize];
    U32 values[] = {0x10203040u, 0xA1B2C3D4u, 0x55667788u};
    U8 write[5u + sizeof(values)] = {
        CmsisDapCommand_TransferBlock, 0u,
        (U8)ArrayCount(values), 0u, 0x0Du,
    };
    for (U32 i = 0u; i < ArrayCount(values); i++) {
        write_le32(write + 5u + i * 4u, values[i]);
    }

    configure_mem_ap(dap, 0x23000052u, RamBase + 0x100u);
    CHECK(execute(dap, write, sizeof(write), response) == 4u);
    CHECK(read_le16(response + 1) == ArrayCount(values));
    CHECK(response[3] == SwdAck_Ok);

    configure_mem_ap(dap, 0x23000052u, RamBase + 0x100u);
    U8 read[] = {
        CmsisDapCommand_TransferBlock, 0u,
        (U8)ArrayCount(values), 0u, 0x0Fu,
    };
    CHECK(execute(dap, read, sizeof(read), response) ==
          4u + sizeof(values));
    CHECK(read_le16(response + 1) == ArrayCount(values));
    CHECK(response[3] == SwdAck_Ok);
    for (U32 i = 0u; i < ArrayCount(values); i++) {
        CHECK(read_le32(response + 4u + i * 4u) == values[i]);
    }
}

static void test_error_recovery(CmsisDap *dap, Target *target) {
    U8 response[CmsisDapPacketSize];
    U8 configure[] = {
        CmsisDapCommand_TransferConfigure, 0u, 2u, 0u, 0u, 0u,
    };
    CHECK(execute(dap, configure, sizeof(configure), response) == 2u);

    U8 read_id[] = {CmsisDapCommand_Transfer, 0u, 1u, 0x02u};
    target->wait_responses = 2u;
    CHECK(execute(dap, read_id, sizeof(read_id), response) == 7u);
    CHECK(response[1] == 1u && response[2] == SwdAck_Ok);
    CHECK(read_le32(response + 3) == DpIdcode);

    target->next_ack = SwdAck_Fault;
    CHECK(execute(dap, read_id, sizeof(read_id), response) == 3u);
    CHECK(response[1] == 0u && response[2] == SwdAck_Fault);

    target->next_ack = SwdAck_Error;
    CHECK(execute(dap, read_id, sizeof(read_id), response) == 3u);
    CHECK(response[1] == 0u && response[2] == SwdAck_Error);
}

static U32 random_next(U32 *state) {
    U32 value = *state;
    value ^= value << 13;
    value ^= value >> 17;
    value ^= value << 5;
    *state = value;
    return value;
}

static void test_malformed_packets(Bsp_SwdPort const *port) {
    CmsisDap dap;
    CHECK(cmsis_dap_init(&dap, port, "0123456789ABCDEF", "1.2.3-test", 0, 0));

    U8 truncated[] = {CmsisDapCommand_Transfer, 0u, 1u};
    U8 response[CmsisDapPacketSize + 16u];
    CHECK(cmsis_dap_execute(&dap, truncated, sizeof(truncated), response,
                            CmsisDapPacketSize) == 2u);
    CHECK(response[1] == CmsisDapStatus_Error);

    U32 random = 0x5E7A4D21u;
    for (U32 iteration = 0u; iteration < 20000u; iteration++) {
        U8 request[CmsisDapPacketSize];
        for (U32 i = 0u; i < sizeof(request); i++) {
            request[i] = (U8)random_next(&random);
        }
        request[0] &= 0x1Fu;
        U16 request_size = (U16)(1u + random_next(&random) % sizeof(request));
        memset(response, 0xA5, sizeof(response));

        U16 size = cmsis_dap_execute(&dap, request, request_size, response,
                                     CmsisDapPacketSize);
        CHECK(size <= CmsisDapPacketSize);
        for (U32 i = CmsisDapPacketSize; i < sizeof(response); i++) {
            CHECK(response[i] == 0xA5u);
        }
        if (dap.debug_port != CmsisDapPort_Disabled) {
            cmsis_dap_disconnect(&dap);
        }
    }
}

int main(void) {
    Target target = {.ap_csw = 0x23000052u};
    active_target = &target;
    Bsp_SwdPort port = {0};
    CmsisDap dap;
    CHECK(cmsis_dap_init(&dap, &port, "0123456789ABCDEF", "1.2.3-test", 0, 0));

    test_basic_commands(&dap);
    test_memory_transfers(&dap);
    test_error_recovery(&dap, &target);
    test_malformed_packets(&port);

    puts("PASS cmsis-dap: commands, memory, recovery, malformed packets");
    return 0;
}
